public class TransferService
{
    private readonly IAccountRepository _accounts;

    public async Task TransferAsync(Guid fromId, Guid toId, decimal amount)
    {
        if (fromId == toId) throw new InvalidOperationException("Cannot transfer to self");
        if (amount <= 0) throw new ArgumentException("Amount must be positive");

        var from = await _accounts.GetByIdAsync(fromId);
        var to = await _accounts.GetByIdAsync(toId);

        if (from.Balance < amount)
            throw new InvalidOperationException("Insufficient funds");

        from.Withdraw(amount);
        to.Deposit(amount);

        await _accounts.SaveAsync(from);
        await _accounts.SaveAsync(to);

        await _auditLog.LogAsync(new AuditEntry
        {
            Action = "Transfer",
            FromAccountId = fromId,
            ToAccountId = toId,
            Amount = amount,
            Timestamp = DateTime.UtcNow
        });
    }
}

public class FraudDetectionService
{
    public bool IsSuspicious(Account account, Transaction transaction)
    {
        var recent = account.Transactions.Where(t =>
            t.Timestamp > DateTime.UtcNow.AddMinutes(-10));
        return recent.Sum(t => t.Amount) > 10000 || transaction.Amount > 50000;
    }
}
